import{_ as t,o as e,c as r,a3 as l}from"./chunks/framework.Dj4Lt7vj.js";const u=JSON.parse('{"title":"知识库是什么","description":"","frontmatter":{"title":"知识库是什么"},"headers":[],"relativePath":"knowledge/basics.md","filePath":"knowledge/basics.md","lastUpdated":1787948622000}'),o={name:"knowledge/basics.md"};function i(d,a,s,n,c,h){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="知识库是什么" tabindex="-1">知识库是什么 <a class="header-anchor" href="#知识库是什么" aria-label="Permalink to &quot;知识库是什么&quot;">​</a></h1><p>知识库是 AI 回答的依据。AI 设置决定它「怎么说」，知识库决定它「知道什么」。没有知识库，AI 只能泛泛而谈；有了知识库，它才能答出你店铺的发货时效、退换规则和商品细节。</p><h2 id="知识库和方案的关系" tabindex="-1">知识库和方案的关系 <a class="header-anchor" href="#知识库和方案的关系" aria-label="Permalink to &quot;知识库和方案的关系&quot;">​</a></h2><p>知识库<strong>独立于方案</strong>存在：先建库、再把库绑定到方案上。</p><ul><li>一个知识库可以绑定给多个方案。</li><li>一个方案也可以绑定多个知识库。</li></ul><p>比如「售后政策库」全店通用，绑给所有方案；「女装商品库」只绑给女装店的方案。</p><h2 id="两类库" tabindex="-1">两类库 <a class="header-anchor" href="#两类库" aria-label="Permalink to &quot;两类库&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>店铺库</th><th>通用库</th></tr></thead><tbody><tr><td>内容来源</td><td>以商品学习抓取的商品资料为主</td><td>手动录入或导入的资料为主</td></tr><tr><td>典型内容</td><td>商品标题、规格、价格</td><td>政策、说明、常见问答</td></tr></tbody></table><p>打开一个知识库，里面有两个标签页：</p><ul><li><strong>知识项</strong>：你录入或导入的问答、文本和文档。</li><li><strong>商品</strong>：商品学习自动抓回来的商品资料，见<a href="/aicare-docs/knowledge/product-learn">商品学习</a>。</li></ul><p>AI 回复时两类内容都会被检索，只是来源不同。</p><h2 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to &quot;入口&quot;">​</a></h2><ul><li><strong>客户端</strong>：左侧菜单「扩展市场」→「知识库」，这里能看到「我的库」和「公共库」。公共库是平台提供的通用资料，可以直接绑定使用。</li><li><strong>方案编辑器</strong>：「知识库」模块，管理当前方案绑定了哪些库，也是发起店铺学习的入口。</li><li><strong>网页工作台</strong>：「知识库」标签页，见<a href="/aicare-docs/workspace/knowledge">管理知识库</a>。</li></ul><h2 id="从零开始建议这样建" tabindex="-1">从零开始建议这样建 <a class="header-anchor" href="#从零开始建议这样建" aria-label="Permalink to &quot;从零开始建议这样建&quot;">​</a></h2><ol><li>建一个通用库，放三类内容：发货说明、退换政策、高频问答。见<a href="/aicare-docs/knowledge/qa-and-files">录入问答和文档</a>。</li><li>对主要店铺跑一次<a href="/aicare-docs/knowledge/product-learn">商品学习</a>，把商品资料抓进店铺库。</li><li>把两个库都绑定到方案，用<a href="/aicare-docs/solution/test">对话测试</a>验证效果。</li><li>之后每周处理一次 AI 报告的知识缺口，持续补内容。</li></ol>',15)])])}const _=t(o,[["render",i]]);export{u as __pageData,_ as default};
